import React, { useEffect, useState } from "react";
import axios from "axios";

function Dashboard() {
  const [transactions, setTransactions] = useState([]);
  const [title, setTitle] = useState("");
  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [date, setDate] = useState("");
  const [notes, setNotes] = useState("");
  const [page, setPage] = useState(1);

  const token = localStorage.getItem("token");

  const fetchTransactions = async () => {
    const res = await axios.get(
      `http://localhost:5000/transactions?page=${page}`,
      {
        headers: { authorization: token },
      }
    );
    setTransactions(res.data);
  };

  useEffect(() => {
    fetchTransactions();
  }, [page]);

  const addTransaction = async () => {
    await axios.post(
      "http://localhost:5000/transactions",
      { title, amount, category, date, notes },
      { headers: { authorization: token } }
    );

    fetchTransactions();
  };

  const deleteTransaction = async (id) => {
    await axios.delete(`http://localhost:5000/transactions/${id}`, {
      headers: { authorization: token },
    });

    fetchTransactions();
  };

  const totalExpense = transactions.reduce(
    (acc, t) => acc + parseFloat(t.amount),
    0
  );

  const handleLogout = () => {
    localStorage.removeItem("token");
    window.location.href = "/";
  };

  return (
    <div>
      <h2>Dashboard</h2>
      <button onClick={handleLogout}>Logout</button>

      <h3>Total Expense: ₹ {totalExpense}</h3>

      <h3>Add Transaction</h3>
      <input placeholder="Title" onChange={(e) => setTitle(e.target.value)} />
      <input placeholder="Amount" onChange={(e) => setAmount(e.target.value)} />
      <input placeholder="Category" onChange={(e) => setCategory(e.target.value)} />
      <input type="date" onChange={(e) => setDate(e.target.value)} />
      <input placeholder="Notes" onChange={(e) => setNotes(e.target.value)} />
      <button onClick={addTransaction}>Add</button>

      <h3>Transactions</h3>
      {transactions.length === 0 && <p>No transactions found</p>}

      {transactions.map((t) => (
        <div key={t.id} style={{ border: "1px solid gray", margin: "10px" }}>
          <p>{t.title} - ₹{t.amount}</p>
          <p>{t.category}</p>
          <p>{t.date}</p>
          <button onClick={() => deleteTransaction(t.id)}>Delete</button>
        </div>
      ))}

      <button onClick={() => setPage(page + 1)}>Load More</button>
    </div>
  );
}

export default Dashboard;
